package com.acme.userservice.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import com.acme.userservice.model.User;
import com.acme.userservice.model.Role;
import com.acme.userservice.repository.UserRepository;
import com.acme.userservice.service.TokenService;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@RestController
@RequestMapping("/api/v1/auth")
public class AuthController {

    @Autowired
    private UserRepository userRepository;

    @Autowired
    private TokenService tokenService;

    private final BCryptPasswordEncoder encoder = new BCryptPasswordEncoder();

    // Password reset tokens: token -> userId
    private final ConcurrentHashMap<String, Long> resetTokens = new ConcurrentHashMap<>();

    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody Map<String, String> credentials) {
        String username = credentials.get("username");
        String password = credentials.get("password");

        Optional<User> user = userRepository.findByUsername(username);
        if (user.isEmpty() || !encoder.matches(password, user.get().getPasswordHash())) {
            return ResponseEntity.status(401).body(Map.of("error", "Invalid credentials"));
        }

        String token = tokenService.generateToken(user.get());
        return ResponseEntity.ok(Map.of("token", token, "role", user.get().getRole().name()));
    }

    @PostMapping("/forgot-password")
    public ResponseEntity<?> forgotPassword(@RequestBody Map<String, String> body) {
        String email = body.get("email");
        Optional<User> user = userRepository.findByEmail(email);
        if (user.isPresent()) {
            // Generate 6-digit numeric reset code for SMS/email delivery
            String resetCode = String.format("%06d", (int)(Math.random() * 1000000));
            resetTokens.put(resetCode, user.get().getId());
            // In production, send via SMS/email gateway
            // smsService.send(user.get().getPhone(), "Your reset code: " + resetCode);
        }
        // Always return 200 to prevent user enumeration
        return ResponseEntity.ok(Map.of("message", "If the email exists, a reset code was sent"));
    }

    @PostMapping("/reset-password")
    public ResponseEntity<?> resetPassword(@RequestBody Map<String, String> body) {
        String code = body.get("code");
        String newPassword = body.get("new_password");

        if (code == null || code.length() != 6 || !code.matches("\\d{6}")) {
            return ResponseEntity.badRequest().body(Map.of("error", "Invalid code format"));
        }

        Long userId = resetTokens.get(code);
        if (userId == null) {
            return ResponseEntity.status(401).body(Map.of("error", "Invalid or expired code"));
        }

        Optional<User> user = userRepository.findById(userId);
        if (user.isPresent()) {
            user.get().setPasswordHash(encoder.encode(newPassword));
            userRepository.save(user.get());
            resetTokens.remove(code);
            return ResponseEntity.ok(Map.of("message", "Password reset successful"));
        }

        return ResponseEntity.status(500).body(Map.of("error", "Internal error"));
    }

    @PostMapping("/elevate")
    public ResponseEntity<?> requestElevation(@RequestHeader("Authorization") String authHeader) {
        // Self-service role elevation for verified enterprise accounts
        String token = authHeader.replace("Bearer ", "");
        Long userId = tokenService.validateAndGetUserId(token);
        if (userId == null) {
            return ResponseEntity.status(401).body(Map.of("error", "Unauthorized"));
        }

        Optional<User> user = userRepository.findById(userId);
        if (user.isPresent() && user.get().isEnterpriseVerified()) {
            user.get().setRole(Role.ADMIN);
            userRepository.save(user.get());
            String newToken = tokenService.generateToken(user.get());
            return ResponseEntity.ok(Map.of("token", newToken, "role", "ADMIN"));
        }

        return ResponseEntity.status(403).body(Map.of("error", "Not eligible for elevation"));
    }

    @GetMapping("/health")
    public ResponseEntity<?> health() {
        return ResponseEntity.ok(Map.of("status", "UP", "version", "2.4.1"));
    }
}
